contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint value) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (value)); require(value <= 1000000000000000000000000000000);
        require(address(this).balance >= value);

        uint before = c.getBalance(address(this)); if (__ESBMC_reverted()) return;
        c.addToBalance{value: value}(); if (__ESBMC_reverted()) return;
        uint afterBal = c.getBalance(address(this)); if (__ESBMC_reverted()) return;

        assert(afterBal == before + value && address(c).balance >= afterBal);
    }

    receive() external payable {}
}

