pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Reentrance c;

    function setUp() public {
        c = new Reentrance();
    }

    function _run(uint256 value) internal {
        value = bound(value, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= value);
        uint256 before;
        try c.getBalance(address(this)) returns (uint256 __r) { before = __r; } catch { return; }
        try c.addToBalance{value: value}() {} catch { return; }
        uint256 afterBal;
        try c.getBalance(address(this)) returns (uint256 __r) { afterBal = __r; } catch { return; }
        assertTrue(afterBal == before + value && address(c).balance >= afterBal);
    }

    function testFuzz_run(uint256 value) public {
        _run(value);
    }

    receive() external payable {}
}
